def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def is_upper(s):
    letters = [c for c in s if c.isalpha()]
    return all(c.isupper() for c in letters)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def running_max(nums):
    out, best = [], None
    for n in nums:
        best = n if best is None else max(best, n)
        out.append(best)
    return out

def factorial(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

def second_largest(nums):
    u = sorted(set(nums), reverse=True)
    return u[1] if len(u) > 1 else None

def first_non_repeat(s):
    for ch in s:
        if s.count(ch) == 1:
            return ch
    return ''

def longest_word(text):
    ws = text.split()
    return max(ws, key=len) if ws else ''

def remove_duplicates(nums):
    out = []
    for n in nums:
        if n not in out:
            out.append(n)
    return out

def flatten(nested):
    out = []
    for sub in nested:
        out.extend(sub)
    return out

def digit_product(n):
    p = 1
    for c in str(n):
        p *= int(c)
    return p

def is_palindrome_number(n):
    s = str(n)
    return s == s[::-1]

def is_palindrome(s):
    t = ''.join(c.lower() for c in s if c.isalnum())
    return t == t[::-1]

def merge_sorted(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:]); out.extend(b[j:])
    return out

def common_prefix(strs):
    if not strs:
        return ''
    out = []
    for chars in zip(*strs):
        if len(set(chars)) != 1:
            break
        out.append(chars[0])
    return ''.join(out)

def rotate_left(lst, k):
    if not lst:
        return []
    k %= len(lst)
    return lst[k:] + lst[:k]

def is_perfect_square(n):
    if n < 0:
        return False
    r = int(n ** 0.5)
    return r * r == n

def count_substring(s, sub):
    if not sub:
        return 0
    n, count = 0, 0
    while True:
        idx = s.find(sub, n)
        if idx < 0:
            break
        count += 1
        n = idx + 1
    return count

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out
